  "upgrade.trialHistoryNote": "अगर रउआ Essentials खातिर भुगतान कर रहल बानी आ Business में जानी, त रउआ उहे ग्राहक खाता आ ट्रायल इतिहास रखब। Business में अतिरिक्त सात दिन के ट्रायल शामिल नइखे। अगर रउआ आपन मूल ट्रायल चलत घरी अपग्रेड करीं, त ओकर मूल समाप्ति तारीख रीसेट ना होई।",
  "upgrade.providerConfirmNote": "प्लान बदले खातिर बिलिंग प्रदाता से पुष्टि के जरूरत होला। कवनो कीमत अंतर, प्रोरेशन, आ प्रभावी तारीख बदलाव के मंजूरी देवे से पहिले देखावे के चाहीं। अपग्रेड से कबो दू गो एक साथ सब्सक्रिप्शन ना बने के चाहीं।",
  "upgrade.chargedThroughProviderNote": "प्लान बदलाव के चार्ज बिलिंग प्रदाता से होला। रउआ आपन सब्सक्रिप्शन एह पेज से रद्द कर सकत बानी, आपन वर्तमान प्लान के नीचे Cancel Subscription बटन से, भा Settings से। रद्द करे से राउर भुगतान अवधि के अंत में भविष्य के नवीनीकरण रुक जाई; ई कबो राउर पहुँच एक बेर में खत्म ना करेला। मौजूदा मुफ्त वर्कस्पेस के एह विकल्पन के देखे से चार्ज ना होई।",
