  "billing.cancel.refundWindowOpen": "रउआ आपन पहिलका भुगतान चार्ज के 3 दिन के भीतर रद्द कइनी, एह से रउआ ओह पहिलका भुगतान के रिफंड खातिर पात्र हो सकत बानी। रद्द करे से खुद रिफंड जारी ना होला — {contact} से ओकरा के माँगल।",
