  "exports.eyebrow": "डेटा",
  "exports.title": "एक्सपोर्ट आ बैकअप",
  "exports.subtitleStart": "डाउनलोड हमेशा सीमित रहेला",
  "exports.subtitleRest": " तक। हर फाइल पर बिजनेस के नाम आ बनावे के तारीख लिखल रहेला।",
  "exports.createBusinessFirst": "पहिले बिजनेस बनाईं — एक्सपोर्ट कवनो बिजनेस के होला, ऐप के ना।",
  "exports.lockedTitle": "CSV आ Excel एक्सपोर्ट एगो Business सुविधा ह",
  "exports.lockedDesc": "रउआ के वर्कस्पेस Essentials प्लान पर बा। Business में CSV आ Excel एक्सपोर्ट, स्टॉक के मूल्यांकन, असीमित प्रोडक्ट आ स्टाफ, सप्लायर, खरीदारी आ बंडल मिलेला।",
  "exports.seeBusiness": "देखीं Business में का-कुछ मिलेला",
  "exports.whatTheseAre": "ई फाइल सभ का ह",
  "exports.about1": "हर डेटासेट CSV भा असली Excel वर्कबुक (.xlsx) के रूप में मिलेला — पूरा इन्वेंटरी वर्कबुक खाली Excel में होला, हर डेटासेट खातिर एगो अलग शीट। CSV फाइल Excel, Numbers, Google Sheets आ अधिकतर स्टॉक ऐप में खुल जाला। UTF-8 टेक्स्ट, उद्धरण में बंद अल्पविराम, नोट में लाइन ब्रेक आ कोड में आगे के शून्य सभ सुरक्षित रहेला, आ जवन सेल फॉर्मूला जइसन शुरू होला ओकरा के निष्क्रिय क दिहल जाला ताकि स्प्रेडशीट ओकरा के टेक्स्ट के रूप में खोले।",
  "exports.about2": "Excel फाइल सभ में, SKU, UPC, ISBN आ बारकोड टेक्स्ट सेल होला — कबो वैज्ञानिक संकेतन ना आ कबो काटल शून्य ना — कॉलम के चौड़ाई, हेडर फिल्टर आ मुद्रा भा मात्रा के फॉर्मेट लगावल रहेला। पूरा इन्वेंटरी वर्कबुक में प्रोडक्ट, स्टॉक स्तर, जगह आ मूवमेंट अलग-अलग शीट पर रहेला।",
  "exports.about3": "बहुत बड़ एक्सपोर्ट हर डेटासेट खातिर 20,000 पंक्ति पर रुक जाला — जब अइसन होला त फाइल के नाम में ई लिखल रहेला (truncated-20000), ताकि कवनो अधूरा फाइल पूरा जइसन ना लागे।",
  "exports.about4": "बैकअप रउआ डेटा के एगो स्नैपशॉट ह, एक क्लिक में बहाल करे वाला चीज ना। एकर बहाली हाथ से, पहिले समीक्षा क के करे के काम ह, एही से फाइल के सुरक्षित रखीं — ऐप में कवनो चीज एकरा से मेटावल बिजनेस के फेर से ना बना सकेला। ऐप कोड आ Base44 प्लेटफॉर्म के बैकअप ई फाइल सभ से अलग से संभालल जाला।",
  "exports.about5": "फोटो आ अटैचमेंट ओनकर सहेजल लिंक के रूप में सूचीबद्ध होला — तस्वीर के फाइल खुद डाउनलोड में ना भरल जाला।",
  "exports.backupTitle": "पूरा बैकअप",
  "exports.backupDesc": "एगो फाइल में एह बिजनेस के प्रोडक्ट, जगह, स्टॉक स्तर, पूरा मूवमेंट खाता, सप्लायर, खरीदारी, ऑर्डर, रिटर्न, गिनती आ लिस्टिंग — आ एकर प्रोफाइल सेटिंग भी। एकरा के अइसन जगह रखीं जवन रउआ के नियंत्रण में होखे।",
  "exports.backupIncludes1": "प्रोडक्ट, कोड, लागत आ नोट",
  "exports.backupIncludes2": "जगह आ हर जगह के मात्रा",
