  "import.subtitleStart": "तीन अलग स्प्रेडशीट काम, ताकि दाम के सुधार कबो स्टॉक के रसीद के रूप में ना आ जाये। सब कुछ खाली",
  "import.subtitleRest": " में ही जाला, आ ड्राई रन पास होखे से पहिले कुछ लिखल ना जाला।",
  "import.createBusinessFirst": "पहिले बिजनेस बनाईं — इंपोर्ट कइल प्रोडक्ट कवनो बिजनेस के होला।",
  "import.createBusinessFirstShort": "पहिले बिजनेस बनाईं।",
