  "print.pickOrderHint": "दस्तावेज के पूर्वावलोकन करे खातिर सूची से खरीद ऑर्डर चुनीं।",
  "print.pickCustomerOrderHint": "दस्तावेज के पूर्वावलोकन करे खातिर सूची से ग्राहक ऑर्डर चुनीं।",
  "print.pickReturnHint": "दस्तावेज के पूर्वावलोकन करे खातिर सूची से दर्ज रिटर्न चुनीं।",
  "print.chooseStyleHint": "शैली चुनीं, फेर सूची से प्रोडक्ट चुनीं। पूर्वावलोकन में बिल्कुल ओही देखाई जवन प्रिंटर से निकली।",
  "print.howToReach": "रउआ प्रिंटर तक कइसे पहुँचब",
  "print.howIntro": "ई ऐप रउआ के पहिले से मौजूद प्रिंटर से जुड़ेला — ई खुद प्रिंटर ना ह। ओह तक पहुँचे के चार तरीका बा, आ लेबल दुनो प्लान पर कवनो भी तरीका से प्रिंट होला। पैकिंग स्लिप, खरीद ऑर्डर, सप्लायर दस्तावेज आ रिपोर्ट कनेक्शन जवन भी होखे, Business खातिर ही ह।",
  "print.howBluetoothLead": "Bluetooth।",
  "print.howBluetoothBody": "एह पेज से, डेस्कटॉप Chrome भा Edge पर आ Android Chrome पर: आपन लेबल प्रिंटर चुनीं आ लेबल सीधे ओह पर जाला। ई iOS Safari में काम ना करेला — iPhone पर, Bluetooth प्रिंटिंग मोबाइल ऐप के साथ आवेला। जवन प्रिंटर खाली Zebra ZPL भा Brother के आपन भाषा बोलेला ओह एह पेज के भेजल लेबल के ना समझी; काम करे वाला कहे से पहिले ई असली प्रिंटर पर जाँचल जाला।",
  "print.howWifiLead": "Wi-Fi।",
  "print.howWifiBody": "प्रिंटर के रउआ के दुकान के Wi-Fi पर लगाईं, फेर प्रिंट बटन के इस्तेमाल करीं — ई एह कंप्यूटर पर लगावल प्रिंटर से दुकान के नेटवर्क पर प्रिंट करेला। iPhone पर, AirPrint बनल-बनायल बा: एकही Wi-Fi पर AirPrint प्रिंटर प्रिंट शीट में अपने आप देखाई देला, कवनो तार ना आ कवनो ऐप ना चाहीं, आ ऐप के AirPrint खातिर कवनो खास कोड ना चाहीं। प्रिंटर के AirPrint के समर्थन करे के चाहीं (अधिकतर नया प्रिंटर करेला) आ फोन आ प्रिंटर के एकही Wi-Fi पर होखे के चाहीं।",
  "print.howEthernetLead": "Ethernet।",
  "print.howEthernetBody": "प्रिंटर के Ethernet तार से रउआ के दुकान के नेटवर्क से जोड़ीं, कंप्यूटर पर लगाईं, आ प्रिंट बटन से प्रिंट करीं। Ethernet डेस्कटॉप आ कंप्यूटर के रास्ता ह — iPhone Ethernet तार के इस्तेमाल ना करेला।",
  "print.howUsbLead": "USB।",
  "print.howUsbBody": "प्रिंटर के आपन तार से कंप्यूटर में लगाईं आ प्रिंट बटन के इस्तेमाल करीं — ई ओह पर लगावल प्रिंटर से प्रिंट करेला। USB OTG केबल वाला Android फोन पर, ऊपर के USB बटन सीधे प्रिंटर से बात करेला। iPhone USB से सीधे प्रिंट ना कर सकेला — ओह पर कवनो WebUSB नइखे — एही से Wi-Fi / AirPrint, भा मोबाइल ऐप से Bluetooth के इस्तेमाल करीं।",
  "print.howCordsLead": "तार अबहीं iPhone खातिर काम करेला, एगो कदम दूर से।",
  "print.howCordsBody": "दुकान के कंप्यूटर में लगावल USB प्रिंटर, भा नेटवर्क से तार से जुड़ल Ethernet प्रिंटर, रउआ के iPhone पर दुकान के Wi-Fi (AirPrint / साझा प्रिंटर) से देखाई देला — तार प्रिंटर के नेटवर्क पर मजबूती से रखेला, आ फोन ओह तक बेतार पहुँचेला।",
  "print.howOfflineLead": "अगर इंटरनेट गिर जाये त,",
  "print.howOfflineBody": "एह पेज पर पहिले से मौजूद लेबल आ दस्तावेज अबहीं प्रिंट होला — प्रिंट बटन, लेबल PDF, Bluetooth आ USB के कवनो कनेक्शन ना चाहीं। जवन चीज के इंटरनेट चाहीं ऊ ह पेज आ ओकर प्रोडक्ट के पहिले बेर लोड करे के। पूरा ऑफ़लाइन मोड (बिना कनेक्शन के ऐप में काम करे के) एगो अलग, बड़हन निर्माण ह आ इहाँ एकर दावा ना कइल जाला।",
