  "training.newForYouHelp": "ई पाठ एह खातिर जोड़ल गइल काहे कि राउर भूमिका बढ़ल, भा केहू एकरा रउआ के सौंपलस। ऐप के नया हिस्सा सीखे खातिर ओकरा पूरा करीं।",
