  "training.subtitle": "ऐप के हर हिस्सा सीखीं, कदम-कदम, आपन गति से। राउर पाठ राउर भूमिका से मेल खाला।",
  "training.team.assign": "प्रशिक्षण सौंपीं",
  "training.team.assignedToast": "प्रशिक्षण सौंपल गइल।",
