  "training.team.deadlineFailed": "समय-सीमा सहेजल ना जा सकल।",
  "training.team.deadlineSave": "समय-सीमा सहेजीं",
  "training.team.deadlineSaved": "समय-सीमा सहेजल गइल।",
  "training.team.help": "देखीं कि के का पूरा कइले बा, पाठ सौंपीं, समय-सीमा तय करीं, आ जब प्रशिक्षण समय से पीछे होखे त चेतावनी भेजीं।",
