  "recovery.emailMeCode": "हमार बैकअप ईमेल पर कोड ईमेल करीं",
  "recovery.emailMeCodeHint": "अगर रउआ बैकअप ईमेल सेटअप कइले बानी, त हम उहाँ 6 अंक के कोड भेजब। राउर खाता के रक्षा खातिर, ई पेज हमेशा एकही तरीका से जवाब देला — चाहे कोड भेजल गइल होखे भा ना।",
  "recovery.codeSent": "अगर राउर बैकअप ईमेल फाइल पर बा, त 6 अंक के कोड अब ओकर रास्ता पर बा। ई 10 मिनट में खतम हो जाला।",
  "recovery.codeLabel": "6 अंक के कोड",
