  "rewards.voided": "इनाम रद्द भइल।",
  "workforce.tab.rewards": "इनाम",
  "training.lessons.mgr-give-rewards.step1": "वर्कफोर्स खोलीं आ इनाम दबाईं। टीम सदस्य चुनीं, फेर प्रकार: स्टोर में प्रतिशत छूट, उपहार कार्ड, भा कुछ अउर जवन रउआ आपन शब्द में बताईं।",
  "training.lessons.mgr-give-rewards.step2": "इनाम के छोट नाम दीं आ अगर चाहीं त नोट दीं। ओह आदमी के तुरंते घंटी मिली, आ इनाम ओकर हमार इनाम में ओकर आपन कोड के साथ इंतजार करेला।",
  "training.lessons.mgr-give-rewards.step3": "सीमा, डिज़ाइन से: रउआ खाली स्टाफ के इनाम देत बानी। रउआ खुद के भा दोसर प्रबंधक के इनाम ना दे सकत बानी — प्रबंधक के इनाम दिहल मालिक के फैसला ह, आ ऐप एकरा साफ तरीका से मना कर दी।",
  "training.lessons.mgr-give-rewards.step4": "गल्ला पर, ऊ कोड टाइप करीं जवन टीम सदस्य रउआ के देखावेला आ ओकरा इस्तेमाल कइल चिन्हित करीं — हर कोड एक बेर काम करेला। अगर योजना बदले त रउआ जवन इनाम दिहले रहनी ओकरा रद्द कर सकत बानी; मालिक के उपहार मालिक के रद्द करे के बा।",
  "training.lessons.mgr-give-rewards.title": "आपन स्टाफ के इनाम दिहल",
  "training.lessons.owner-give-rewards.step1": "इनाम वर्कफोर्स में, इनाम टैब पर रहेला, आ ऊ खाली Business प्लान खातिर बा — Essentials पर टैब लॉक दरवाजा देखावेला, ताकि राउर टीम देख सके कि बड़ प्लान में का बा।",
  "training.lessons.owner-give-rewards.step2": "रउआ टीम पर केहू के भी इनाम दे सकत बानी — स्टाफ आ प्रबंधक दुनो के। आदमी चुनीं, फेर प्रकार: स्टोर में प्रतिशत छूट (कवनो प्रतिशत जवन रउआ चुनीं), कहीं के भी उपहार कार्ड, भा कवनो प्रोत्साहन जवन रउआ आपन शब्द में बताईं।",
  "training.lessons.owner-give-rewards.step3": "इनाम ओकर आपन एक-बेर वाला कोड के साथ उतरेला आ ओह आदमी के घंटी बजावेला। ऊ गल्ला पर कोड देखावेला; मालिक भा प्रबंधक एकरा टाइप करके ओकरा इस्तेमाल कइल चिन्हित करेला।",
  "training.lessons.owner-give-rewards.step4": "छपल भा साझा कइल इनाम पर्ची पर खाली राउर बिजनेस के नाम रहेला — कबो ऐप के ना। ई राउर स्टोर के धन्यवाद ह, विज्ञापन ना।",
  "training.lessons.owner-give-rewards.title": "इनाम दिहल (Business प्लान)",
  "training.lessons.owner-rewards-oversight.step1": "राउर प्रबंधक भी इनाम दे सकेला — खाली स्टाफ के। ऐप प्रबंधक के खुद के भा दोसर प्रबंधक के इनाम देवे से मना कर देला; प्रबंधक के इनाम दिहल हमेशा राउर फैसला ह।",
  "training.lessons.owner-rewards-oversight.step2": "रउआ बिजनेस में हर इनाम इनाम इतिहास में देखत बानी: के दिहलस, के पावलस, आ ई तइयार बा, इस्तेमाल भइल बा कि रद्द बा। प्रबंधक खाली ऊ इनाम देखेला जवन ऊ दिहले बा आ जवन ओकरा मिलल बा।",
  "training.lessons.owner-rewards-oversight.step3": "रउआ कवनो इनाम रद्द कर सकत बानी, ओह में ऊ भी शामिल बा जवन राउर प्रबंधक दिहले रहल। प्रबंधक आपन उपहार रद्द कर सकेला, बाकिर कबो राउर ना।",
  "training.lessons.owner-rewards-oversight.step4": "हर कोड ठीक एक बेर काम करेला, आ रद्द इनाम कबो इस्तेमाल ना हो सकेला — इतिहास हमेशा देखावेला कि इनाम कवन तरीका से खतम भइल।",
  "training.lessons.owner-rewards-oversight.title": "इनाम के देखरेख: राउर प्रबंधक के दिहल",
  "training.lessons.staff-your-rewards.step1": "जब राउर प्रबंधक भा मालिक रउआ के इनाम देला, त राउर घंटी बजे ला। वर्कफोर्स खोलीं आ इनाम दबाईं आ ओकरा हमार इनाम के नीचे देखीं।",
  "training.lessons.staff-your-rewards.step2": "हर इनाम के आपन कोड होला। एकरा खुद लगे रखीं — जवन गल्ला पर कोड देखावेला उहे आदमी इनाम इस्तेमाल करेला।",
  "training.lessons.staff-your-rewards.step3": "एकरा इस्तेमाल करे खातिर, जब रउआ खरीदीं त कोड देखाईं। गल्ला पर वाला आदमी एकरा टाइप करेला आ इस्तेमाल कइल चिन्हित करेला — हर कोड ठीक एक बेर काम करेला।",
  "training.lessons.staff-your-rewards.step4": "इनाम Business प्लान के उपहार ह। अगर राउर स्टोर Business पर नइखे, त इनाम टैब ओकर बजाय लॉक दरवाजा देखावेला — ऊ प्लान ह, गलती ना।",
  "training.lessons.staff-your-rewards.title": "राउर इनाम: आपन कोड खोजल आ ओकरा इस्तेमाल करल",
