  "plansLib.includes.support": "ऐप के भीतर से समस्या के रिपोर्ट",
  "support.category.broken": "कुछ टूट गइल बा",
  "support.category.idea": "कवनो विचार की सुझाव",
  "support.category.looksWrong": "कुछ गलत लागत बा",
  "support.category.other": "कुछ अउरी",
  "support.categoryLabel": "ई कवना बारे में बा?",
  "support.contextNote": "जेह से हमनी समस्या खोज सकीं, राउर नोट में अपने-आप शामिल रहेला: रउआ कवना पन्ना पर बानी, चुनल होखे त राउर व्यवसाय आ भूमिका, राउर प्लान, राउर ऐप के भाषा, आ रउआ कवन तरह के फोन की ब्राउज़र इस्तेमाल करत बानी। एह में कबो राउर सामान, स्टॉक की बिक्री शामिल ना होला।",
  "support.description": "कुछ टूटल बा, कुछ गलत लागत बा, की कवनो विचार साझा करे के बा? इहाँ हमनी के बताईं — राउर नोट सीधा ऐप के पीछे के टीम के लगे पहुँचेला।",
  "support.errorGeneric": "ऊ ना भइल। कृपया फेर से कोशिश करीं।",
  "support.errorRateLimit": "रउआ आज कई गो रिपोर्ट भेज चुकल बानी — धन्यवाद। कृपया अउरी भेजे खातिर काल्ह तक इंतजार करीं, जेह से हर रिपोर्ट ठीक से पढ़ल जा सके।",
  "support.errorTooLong": "ई एक रिपोर्ट में समाए वाला से लमहर बा — कृपया तनी छोट क के फेर से भेजीं।",
  "support.errorTooShort": "कृपया हमनी के तनी अउरी बताईं — एक-दु वाक्य हमनी के ओकरा खोजे में मदद करेला।",
  "support.messageLabel": "का भइल रहे?",
  "support.messagePlaceholder": "हमनी के बताईं रउआ का करत रहीं आ का गलत भइल, आपन शब्द में…",
